#pragma once
#include "GroupedWorkfaces.h"
#include "WorkfaceRangeReview.h"
namespace grouped_review {
inline void write(const std::vector<FeatureLine>& source,const std::vector<std::vector<GridCell>>& grid,double cell,const Eigen::Vector4f& origin,
 const grouped::Result& graph,const std::vector<overall::Preview>& rows,const std::string& prefix){
    auto lines=overall::localLines(source,origin);std::ofstream out(prefix+"grouped_workface_review.html");if(!out)throw std::runtime_error("Cannot write grouped review");
    out<<R"HTML(<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>多段工作帮范围核验</title>
<style>body{font:15px system-ui;margin:16px;background:#f4f6f8;color:#182a40}h1{font-size:24px}button,select,input,textarea{font:inherit;padding:6px;margin:4px}button{cursor:pointer}select{max-width:95%}.card{background:white;padding:12px;margin:10px 0;border:1px solid #ccd7df;border-radius:6px}#map{display:block;width:100%;height:65vh;background:white;touch-action:none}#info,#status{white-space:pre-wrap;line-height:1.7}textarea{width:42%;height:80px}label{display:inline-block;margin:4px}#status{color:#934300}.checks label{display:block}small{color:#586b7e}</style>
<h1>多段工作帮范围核验</h1><p>按同级台阶空间连续性归并，保留原始特征线；橙色为上部坡顶，青色为下部坡底，紫色为通过检查的截面。图的终点不是已经确认的真实工作帮边界。</p>
<div class="card"><label>候选<select id="candidate"></select></label><label><input type="checkbox" id="all">包含没有有效截面的候选</label><button id="focus">定位范围</button><button id="fit">全场</button><button id="image">下载当前图 PNG</button><label><input type="checkbox" checked id="sections">显示有效截面</label><label><input type="checkbox" id="failed">显示被拒绝但有目标的截面</label><div id="info"></div></div>
<canvas id="map"></canvas><div class="card"><p>多段边界区间（每行：线编号, 起点米, 终点米）。可缩小已有区间，不允许跨越没有支持的缺口。</p>
<textarea id="upper" aria-label="上部多段坡顶"></textarea><textarea id="lower" aria-label="下部多段坡底"></textarea><br><button id="apply">应用区间</button><label>核验人<input id="reviewer" maxlength="80"></label>
<div class="checks"><label><input id="topCheck" type="checkbox">核实上边界确为本范围最上部坡顶。</label><label><input id="bottomCheck" type="checkbox">核实下边界确为本范围最下部坡底。</label><label><input id="extentCheck" type="checkbox">核实中间台阶归属和缺测，没有把中途断开当成完整边界。</label></div>
<button id="confirm">确认当前范围</button><button id="export">下载多段范围 JSON</button><label>恢复记录<input id="import" type="file" accept=".json"></label><div id="status">自动范围均未确认。人工确认只记录范围，不会自动进入安全评价。</div><small>本页记录格式为 grouped-workface-review/v1，与旧单线范围 JSON 不通用。更改任何区间会撤销确认；导入后须重新确认。几何参数仅为选定范围的候选参数。</small></div>
<script>const D=)HTML";
    out<<std::setprecision(17)<<"{\"dataset\":\""<<range_review::fingerprint(source,grid,cell,origin)<<"\",\"rows\":"<<grid.size()<<",\"cols\":"<<grid[0].size()<<",\"cell\":"<<cell<<",\"truncated\":"<<(graph.truncated?"true":"false")<<",\"lines\":[";
    for(size_t i=0;i<lines.size();++i){auto& l=lines[i];if(i)out<<',';out<<"{\"id\":"<<l.id<<",\"type\":"<<l.type<<",\"p\":[";for(size_t j=0;j<l.p.size();++j){if(j)out<<',';out<<'['<<l.p[j].x()<<','<<l.p[j].y()<<','<<l.s[j]<<']';}out<<"]}";}
    out<<"],\"runs\":[";bool first=true;for(size_t r=0;r<grid.size();++r)for(size_t c=0;c<grid[r].size();){int type=grid[r][c].count>0?grid[r][c].type:-1;size_t e=c+1;while(e<grid[r].size()&&(grid[r][e].count>0?grid[r][e].type:-1)==type)++e;if(!first)out<<',';first=false;out<<'['<<r<<','<<c<<','<<e-c<<','<<type<<']';c=e;}
    auto spans=[&](const std::vector<grouped::Span>& v){out<<'[';for(size_t i=0;i<v.size();++i){if(i)out<<',';out<<'['<<v[i].line<<','<<v[i].begin<<','<<v[i].end<<']';}out<<']';};
    out<<"],\"groups\":[";for(size_t i=0;i<graph.groups.size();++i){auto& g=graph.groups[i];if(i)out<<',';out<<"{\"id\":"<<i<<",\"upper\":";spans(g.crests);out<<",\"lower\":";spans(g.toes);out<<",\"samples\":"<<g.samples.size()<<'}';}
    out<<"],\"candidates\":[";for(size_t i=0;i<graph.candidates.size();++i){auto& c=graph.candidates[i];if(i)out<<',';out<<"{\"name\":\""<<c.name<<"\",\"chain\":[";for(size_t j=0;j<c.chain.size();++j){if(j)out<<',';out<<c.chain[j];}
        out<<"],\"up\":"<<c.upstreamLink<<",\"down\":"<<c.downstreamLink<<",\"upWeak\":"<<c.upstreamWeak<<",\"downWeak\":"<<c.downstreamWeak<<'}';}
    out<<"],\"sections\":[";for(size_t i=0;i<rows.size();++i){auto& s=rows[i];if(i)out<<',';out<<"{\"id\":"<<s.id<<",\"name\":\""<<s.name<<"\",\"upper\":"<<s.upper<<",\"lower\":"<<s.lower<<",\"station\":"<<s.station<<",\"valid\":"<<(s.geometryAvailable?"true":"false")<<",\"target\":"<<(s.hasTarget?"true":"false")<<",\"status\":\""<<s.status<<"\",\"height\":"<<s.height<<",\"angle\":"<<s.angle<<",\"width\":"<<s.width<<",\"a\":["<<s.top.x()-origin.x()<<','<<s.top.y()-origin.y()<<"],\"b\":["<<s.bottom.x()-origin.x()<<','<<s.bottom.y()-origin.y()<<"]}";}
    out<<R"HTML(]};
const $=id=>document.getElementById(id),canvas=$('map'),ctx=canvas.getContext('2d'),lineById=new Map(D.lines.map(l=>[l.id,l])),byName=new Map();
for(const s of D.sections){if(!byName.has(s.name))byName.set(s.name,[]);byName.get(s.name).push(s);}
let active=null,upper=[],lower=[],state='draft',drag=null,view=[D.cols*D.cell/2,D.rows*D.cell/2,D.cols*D.cell*1.04],confirmedAt=null;
const copy=x=>JSON.parse(JSON.stringify(x)),msg=s=>$('status').textContent=s;
const statusNames={extent_unconfirmed:'几何通过，范围未确认',incomplete_chain_intersection:'无法贯穿全部台阶边界',crossing_sections:'截面相交',incomplete_observed_profile:'观测缺失',insufficient_multiple_bench_evidence:'多台阶证据不足',possible_opposite_wall_or_uphill_crossing:'疑似跨另一侧边坡',unobserved_endpoint:'端点缺测',lower_not_below_upper:'上下高程不符',missing_upper_line:'缺少上边界',unstable_upper_direction:'上边界方向不稳定'};
const base=document.createElement('canvas');base.width=D.cols;base.height=D.rows;const bx=base.getContext('2d'),colors={'-1':'#fafafa',0:'#eee',1:'#92c997',2:'#dfa09c',4:'#ffe05c'};
for(const [r,c,n,t] of D.runs){bx.fillStyle=colors[t]||'#eee';bx.fillRect(c,D.rows-1-r,n,1);}
function populate(){const previous=$('candidate').value;$('candidate').replaceChildren();const list=D.candidates.filter(c=>$('all').checked||(byName.get(c.name)||[]).some(s=>s.valid));list.sort((a,b)=>b.chain.length-a.chain.length||(byName.get(b.name)||[]).filter(s=>s.valid).length-(byName.get(a.name)||[]).filter(s=>s.valid).length);
for(const c of list){const o=document.createElement('option');o.value=c.name;o.textContent=`${c.name} / ${c.chain.length} 级 / ${(byName.get(c.name)||[]).filter(s=>s.valid).length} 条有效截面`; $('candidate').append(o);}if(list.some(c=>c.name===previous))$('candidate').value=previous;select();}
function encode(v){return v.map(x=>x.join(',')).join('\n');}
function invalidate(){state='draft';confirmedAt=null;for(const id of ['topCheck','bottomCheck','extentCheck'])$(id).checked=false;msg('未确认：修改后需重新核验。');}
function select(){active=D.candidates.find(c=>c.name===$('candidate').value);invalidate();if(!active)return;upper=copy(D.groups[active.chain[0]].upper);lower=copy(D.groups[active.chain.at(-1)].lower);$('upper').value=encode(upper);$('lower').value=encode(lower);info();draw();}
function parse(text,allowed){const v=text.trim().split(/\r?\n/).filter(Boolean).map(s=>s.split(',').map(Number));if(!v.length)throw Error('边界不能为空');for(const a of v){if(a.length!==3||!a.every(Number.isFinite)||!Number.isInteger(a[0])||a[2]<=a[1]||!allowed.some(b=>a[0]===b[0]&&a[1]>=b[1]-1e-7&&a[2]<=b[2]+1e-7))throw Error('区间越界或格式错误；只能缩小已有支持区间');}return v;}
function stationAt(l,p){let best=Infinity,station=0;for(let i=1;i<l.p.length;i++){const a=l.p[i-1],b=l.p[i],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy))),d=Math.hypot(p[0]-a[0]-t*dx,p[1]-a[1]-t*dy);if(d<best){best=d;station=a[2]+t*(b[2]-a[2]);}}return station;}
function visible(s){if(!s.target)return false;return upper.some(v=>v[0]===s.upper&&s.station>=v[1]&&s.station<=v[2])&&lower.some(v=>v[0]===s.lower&&stationAt(lineById.get(v[0]),s.b)>=v[1]-1e-7&&stationAt(lineById.get(v[0]),s.b)<=v[2]+1e-7);}
function info(){if(!active)return;const rows=byName.get(active.name)||[],valid=rows.filter(s=>s.valid&&visible(s)),counts={};for(const s of rows)counts[s.status]=(counts[s.status]||0)+1;
$('info').textContent=`台阶链：${active.chain.join(' → ')}；当前区间有效截面 ${valid.length}/${rows.length}。\n上游其他位置存在连接：${active.up?'有':'未发现'}；下游：${active.down?'有':'未发现'}；弱连接：${active.upWeak||active.downWeak?'有，须核查':'未发现'}。\n${valid.length?`候选高差 ${Math.min(...valid.map(s=>s.height)).toFixed(2)}–${Math.max(...valid.map(s=>s.height)).toFixed(2)} m；整体倾角 ${Math.min(...valid.map(s=>s.angle)).toFixed(2)}–${Math.max(...valid.map(s=>s.angle)).toFixed(2)}°。\n`:''}拒绝/通过明细：${Object.entries(counts).map(([k,v])=>(statusNames[k]||k)+': '+v).join('；')}\n${D.truncated?'警告：候选枚举达到上限。':'候选枚举未截断。'} 未发现连接不等于已到达真实边界。`;}
function transform(){const w=canvas.clientWidth,h=canvas.clientHeight,scale=w/view[2];return {w,h,scale,x:p=>w/2+(p[0]-view[0])*scale,y:p=>h/2-(p[1]-view[1])*scale};}
function stroke(points,color,width){if(points.length<2)return;const t=transform();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach((p,i)=>ctx[i?'lineTo':'moveTo'](t.x(p),t.y(p)));ctx.stroke();}
function clip(span){const l=lineById.get(span[0]);if(!l)return [];const result=[];for(let i=1;i<l.p.length;i++){const a=l.p[i-1],b=l.p[i],lo=Math.max(a[2],span[1]),hi=Math.min(b[2],span[2]);if(hi<lo)continue;for(const s of [lo,hi]){const f=(s-a[2])/(b[2]-a[2]);result.push([a[0]+f*(b[0]-a[0]),a[1]+f*(b[1]-a[1])]);}}return result;}
function draw(){const t=transform(),dpr=devicePixelRatio||1;canvas.width=Math.round(t.w*dpr);canvas.height=Math.round(t.h*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='white';ctx.fillRect(0,0,t.w,t.h);ctx.imageSmoothingEnabled=false;ctx.drawImage(base,t.x([0,0]),t.y([0,D.rows*D.cell]),D.cols*D.cell*t.scale,D.rows*D.cell*t.scale);
for(const l of D.lines)stroke(l.p,l.type===0?'#252c38':'#3c62b2',.6);if(!active)return;for(const id of active.chain)for(const span of [...D.groups[id].upper,...D.groups[id].lower])stroke(clip(span),'#aa7900',1.1);
for(const s of byName.get(active.name)||[])if(visible(s)&&((s.valid&&$('sections').checked)||(!s.valid&&$('failed').checked)))stroke([s.a,s.b],s.valid?'#8639b0':'#ad2838',s.valid?1.4:.7);
for(const span of upper)stroke(clip(span),'#e78200',3);for(const span of lower)stroke(clip(span),'#00aabc',3);ctx.font='14px sans-serif';ctx.fillStyle='#182a40';ctx.fillText(`${active.name} / ${active.chain.length}级 / ${state==='range_confirmed'?'人工范围已确认':'范围待核验'}`,12,22);}
function focus(){const points=[...upper,...lower].flatMap(clip);if(!points.length)return;const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys);view=[(xmin+xmax)/2,(ymin+ymax)/2,Math.max(xmax-xmin,(ymax-ymin)*canvas.clientWidth/canvas.clientHeight)*1.2+10];draw();}
function record(){return {schema:'grouped-workface-review/v1',dataset:D.dataset,candidate:active.name,chain:[...active.chain],upper:copy(upper),lower:copy(lower),reviewer:$('reviewer').value.trim(),state,confirmed_at:confirmedAt,checks:['topCheck','bottomCheck','extentCheck'].map(id=>$(id).checked),geometry_scope:'candidate_only_not_safety_evaluation'};}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('candidate').onchange=select;$('all').onchange=populate;$('focus').onclick=focus;$('fit').onclick=()=>{view=[D.cols*D.cell/2,D.rows*D.cell/2,D.cols*D.cell*1.04];draw();};
for(const id of ['sections','failed'])$(id).onchange=draw;
for(const id of ['upper','lower','reviewer'])$(id).oninput=()=>{invalidate();draw();};for(const id of ['topCheck','bottomCheck','extentCheck'])$(id).onchange=()=>{state='draft';confirmedAt=null;msg('核验选项已改变，请重新确认。');draw();};
$('apply').onclick=()=>{try{const u=parse($('upper').value,D.groups[active.chain[0]].upper),l=parse($('lower').value,D.groups[active.chain.at(-1)].lower);upper=u;lower=l;invalidate();info();draw();}catch(e){msg(e.message);}};
function unchanged(){return JSON.stringify(parse($('upper').value,D.groups[active.chain[0]].upper))===JSON.stringify(upper)&&JSON.stringify(parse($('lower').value,D.groups[active.chain.at(-1)].lower))===JSON.stringify(lower);}
$('confirm').onclick=()=>{try{if(!unchanged())throw Error('请先应用区间');if(!$('reviewer').value.trim()||!['topCheck','bottomCheck','extentCheck'].every(id=>$(id).checked))throw Error('请填写核验人并逐项核验');if(!(byName.get(active.name)||[]).some(s=>s.valid&&visible(s)))throw Error('当前区间没有通过检查的截面，只能保留草稿');state='range_confirmed';confirmedAt=new Date().toISOString();msg('人工范围确认已记录。请下载 JSON；不代表已完成安全评价。');draw();}catch(e){msg(e.message);}};
$('export').onclick=()=>{try{if(!unchanged())throw Error('请先应用区间');download(new Blob([JSON.stringify(record(),null,2)],{type:'application/json'}),'grouped_workface_range.json');}catch(e){msg(e.message);}};
$('import').onchange=async e=>{try{const r=JSON.parse(await e.target.files[0].text());if(r.schema!=='grouped-workface-review/v1'||r.dataset!==D.dataset)throw Error('格式或数据指纹不匹配，拒绝导入');const c=D.candidates.find(c=>c.name===r.candidate);if(!c||JSON.stringify(c.chain)!==JSON.stringify(r.chain)||!Array.isArray(r.upper)||!Array.isArray(r.lower)||typeof r.reviewer!=='string'||r.reviewer.length>80)throw Error('候选或台阶链无效');const u=parse(encode(r.upper),D.groups[c.chain[0]].upper),l=parse(encode(r.lower),D.groups[c.chain.at(-1)].lower);$('all').checked=true;populate();$('candidate').value=c.name;select();upper=u;lower=l;$('upper').value=encode(u);$('lower').value=encode(l);$('reviewer').value=r.reviewer;invalidate();info();draw();msg('记录已恢复为草稿，请重新核验确认。');}catch(e){msg(e.message);}finally{e.target.value='';}};
$('image').onclick=()=>canvas.toBlob(b=>download(b,active.name+'.png'));
canvas.onpointerdown=e=>{canvas.setPointerCapture(e.pointerId);drag={x:e.offsetX,y:e.offsetY,view:[...view]};};canvas.onpointermove=e=>{if(!drag)return;const scale=canvas.clientWidth/drag.view[2];view=[drag.view[0]-(e.offsetX-drag.x)/scale,drag.view[1]+(e.offsetY-drag.y)/scale,drag.view[2]];draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;canvas.onwheel=e=>{e.preventDefault();view[2]=Math.min(D.cols*D.cell*2,Math.max(20,view[2]*Math.exp(e.deltaY*.001)));draw();};
new ResizeObserver(draw).observe(canvas);populate();
</script></html>)HTML";
}
}
